const modi = require('modi');

const bundle = new modi.MODI();
const imu = bundle.imus[0];
const display = bundle.displays[0];

let dice = 0;

while (true) {
    while (imu.shaking > 30) {
        dice = Math.floor(Math.random() * 6) + 1;
        display.writeText(String(dice));
    }
    display.writeText(String(dice));
}

